export async function loadCatalog(){const response=await fetch('./data/catalog.json',{cache:'no-cache'});if(!response.ok)throw new Error(`Unable to load concept catalog (${response.status}).`);return response.json();}
export async function loadConcept(entry){const response=await fetch(entry.metadata,{cache:'no-cache'});if(!response.ok)throw new Error(`Unable to load ${entry.title}.`);const data=await response.json();data.__metadataUrl=new URL(entry.metadata,document.baseURI).href;data.__freshnessStatus=entry.freshnessStatus||'unknown';data.__reviewAgeDays=entry.reviewAgeDays??null;data.__categoryLabels=entry.categoryLabels||[];return data;}
